async function u(i=1){const o=`${window.APP_CONFIG?.baseUrl||"/"}api/regions?country_id=${i}`;try{const r=await(await fetch(o)).json();return r.success?r.data.map(t=>({id:t.id,name:t.region})):[]}catch(e){return console.error("Fetch Regions Error:",e),[]}}function g(i){const n=document.getElementById(i);if(!n)return;const o=n.querySelector('select[name="countryId"]')||n.querySelector('select[name="country_id"]'),e=n.querySelector('select[name="regionId"]')||n.querySelector('select[name="region_id"]');!o||!e||o.addEventListener("change",async r=>{const t=o.value,a=r.detail?.preSelectedRegionId;if(!t){e.innerHTML='<option value="">Select Region</option>';return}e.innerHTML='<option value="">Loading...</option>',e.disabled=!0;try{const l=(await u(t)).map(c=>{const d=a&&String(c.id)===String(a);return`<option value="${c.id}" ${d?"selected":""}>${c.name}</option>`}).join("");e.innerHTML=`
                <option value="">Select Region</option>
                ${l}
            `}catch(s){console.error("Failed to reload regions:",s),e.innerHTML='<option value="">Error loading regions</option>'}finally{e.disabled=!1}})}export{g as e,u as f};
